

Netflix Customer Intelligence, Churn Prediction & AI Analytics Copilot
SQL Business Questions — PostgreSQL Solutions (Q1–Q37)
---
--Q1. How many active customers does the platform currently have, by country?

SELECT
    c.country,
    COUNT(DISTINCT c.customer_id) AS active_customers
FROM customers c
JOIN subscriptions s
    ON c.customer_id = s.customer_id
WHERE s.subscription_status = 'Active'
GROUP BY c.country
ORDER BY active_customers DESC;

--Q2. What is the total and average monthly revenue generated by each subscription plan?

SELECT
    sp.plan_name,
    SUM(s.monthly_price) AS total_monthly_revenue,
    ROUND(AVG(s.monthly_price), 2) AS average_monthly_revenue
FROM subscriptions s
JOIN subscription_plans sp
    ON s.plan_id = sp.plan_id
WHERE s.subscription_status = 'Active'
GROUP BY sp.plan_name
ORDER BY total_monthly_revenue DESC;

--Q3. What is the overall churn rate (percentage of customers with churned = true)?

SELECT
    ROUND(
        100.0 * COUNT(*) FILTER (WHERE churned = TRUE)
        / COUNT(*),
        2
    ) AS churn_rate_percentage
FROM churn_labels;

--Q4. Which acquisition channel has brought in the most customers, and what is the churn rate for each channel?

SELECT
    c.acquisition_channel,
    COUNT(DISTINCT c.customer_id) AS total_customers,
    ROUND(
        100.0 *
        COUNT(DISTINCT CASE WHEN cl.churned THEN c.customer_id END)
        / COUNT(DISTINCT c.customer_id),
        2
    ) AS churn_rate_percentage
FROM customers c
LEFT JOIN churn_labels cl
    ON c.customer_id = cl.customer_id
GROUP BY c.acquisition_channel
ORDER BY total_customers DESC;

--Q5. What is the average customer age by subscription plan?

SELECT
    sp.plan_name,
    ROUND(AVG(c.age), 2) AS average_customer_age
FROM customers c
JOIN subscriptions s
    ON c.customer_id = s.customer_id
JOIN subscription_plans sp
    ON s.plan_id = sp.plan_id
WHERE s.subscription_status = 'Active'
GROUP BY sp.plan_name;

--Q6. List the top 10 most-watched titles by total watch_duration_minutes.

SELECT
    c.title,
    SUM(v.watch_duration_minutes) AS total_watch_minutes
FROM viewing_activity v
JOIN content c
    ON v.content_id = c.content_id
GROUP BY c.content_id, c.title
ORDER BY total_watch_minutes DESC
LIMIT 10;

--Q7. What is the average completion_percentage by content_type and genre?

SELECT
    c.content_type,
    c.genre,
    ROUND(AVG(v.completion_percentage), 2) AS average_completion_percentage
FROM viewing_activity v
JOIN content c
    ON v.content_id = c.content_id
GROUP BY c.content_type, c.genre
ORDER BY c.content_type, average_completion_percentage DESC;

--Q8. How many failed payments occurred in each of the last 12 months?

SELECT
    DATE_TRUNC('month', payment_date)::date AS payment_month,
    COUNT(*) AS failed_payments
FROM payments
WHERE payment_status = 'Failed'
  AND payment_date >=
      DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '11 months'
GROUP BY payment_month
ORDER BY payment_month;

--Q9. What is the average resolution_time_hours by issue_category?

SELECT
    issue_category,
    COUNT(*) AS resolved_tickets,
    ROUND(AVG(resolution_time_hours), 2) AS avg_resolution_hours
FROM support_tickets
WHERE ticket_status IN ('Resolved', 'Closed')
  AND resolution_time_hours IS NOT NULL
GROUP BY issue_category
ORDER BY avg_resolution_hours DESC;

--Q10. What is the distribution of customer_satisfaction_score across all resolved/closed support tickets?

SELECT
    customer_satisfaction_score AS satisfaction_score,
    COUNT(*) AS ticket_count,
    ROUND(
        100.0 * COUNT(*) /
        SUM(COUNT(*)) OVER (), 2
    ) AS percentage
FROM support_tickets
WHERE ticket_status IN ('Resolved', 'Closed')
  AND customer_satisfaction_score IS NOT NULL
GROUP BY customer_satisfaction_score
ORDER BY satisfaction_score;


--Q11. Which device_type generates the most total viewing minutes?

SELECT
    device_type,
    SUM(watch_duration_minutes) AS total_viewing_minutes
FROM viewing_activity
GROUP BY device_type
ORDER BY total_viewing_minutes DESC;

--Q12. What is the average rating from customer_feedback, grouped by sentiment_label?

SELECT
    sentiment_label,
    ROUND(AVG(rating), 2) AS average_rating
FROM customer_feedback
GROUP BY sentiment_label
ORDER BY average_rating DESC;

--Q13. How many customers signed up through each acquisition_channel in each calendar year?

SELECT
    EXTRACT(YEAR FROM registration_date) AS registration_year,
    acquisition_channel,
    COUNT(*) AS customers_signed_up
FROM customers
GROUP BY registration_year, acquisition_channel
ORDER BY registration_year, customers_signed_up DESC;

--Q14. What percentage of customers have auto_renew turned off?

SELECT
    ROUND(
        100.0 * COUNT(*) FILTER (WHERE auto_renew = FALSE)
        / COUNT(*),
        2
    ) AS auto_renew_off_percentage
FROM subscriptions;

--Q15. List all customers who have raised more than 3 support tickets, along with their total ticket count.

SELECT
    customer_id,
    COUNT(*) AS total_support_tickets
FROM support_tickets
GROUP BY customer_id
HAVING COUNT(*) > 3
ORDER BY total_support_tickets DESC;


--Q16. Using RANK(), rank subscription plans by total revenue generated (monthly_price × count of active subscriptions).

SELECT
    sp.plan_name,
    SUM(s.monthly_price) AS total_revenue,
    RANK() OVER (
        ORDER BY SUM(s.monthly_price) DESC
    ) AS revenue_rank
FROM subscriptions s
JOIN subscription_plans sp
    ON s.plan_id = sp.plan_id
WHERE s.subscription_status = 'Active'
GROUP BY sp.plan_name;

--Q17. For each customer, use ROW_NUMBER() to identify their most recent support ticket and return only that row.

SELECT
    customer_id,
    ticket_id,
    ticket_date,
    issue_category,
    ticket_status
FROM (
    SELECT
        customer_id,
        ticket_id,
        ticket_date,
        issue_category,
        ticket_status,
        ROW_NUMBER() OVER (
            PARTITION BY customer_id
            ORDER BY ticket_date DESC NULLS LAST
        ) AS rn
    FROM support_tickets
) t
WHERE rn = 1
ORDER BY customer_id;

--Q18. Calculate a 3-month moving average of new customer registrations using a window function.

WITH monthly_registrations AS (
    SELECT
        DATE_TRUNC('month', registration_date)::date AS month,
        COUNT(*) AS new_customers
    FROM customers
    GROUP BY month
)
SELECT
    month,
    new_customers,
    ROUND(
        AVG(new_customers) OVER (
            ORDER BY month
            ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
        ),
        2
    ) AS three_month_moving_average
FROM monthly_registrations
ORDER BY month;

--Q19. Using LAG(), identify customers whose monthly watch time in the most recent month is lower than their watch time in the prior month.

WITH monthly_watch AS (
    SELECT
        customer_id,
        DATE_TRUNC('month', viewing_date)::date AS month,
        SUM(watch_duration_minutes) AS watch_minutes
    FROM viewing_activity
    GROUP BY customer_id, month
),
with_previous AS (
    SELECT
        *,
        LAG(watch_minutes) OVER (
            PARTITION BY customer_id
            ORDER BY month
        ) AS previous_month_watch
    FROM monthly_watch
)
SELECT *
FROM with_previous
WHERE month = (SELECT MAX(month) FROM monthly_watch)
  AND watch_minutes < previous_month_watch;


--Q20. Build a customer acquisition cohort analysis: percentage of each cohort still active at 1, 3, and 6 months after registration.

WITH cohorts AS (
    SELECT
        customer_id,
        DATE_TRUNC('month', registration_date)::date AS cohort_month
    FROM customers
),

cohort_activity AS (
    SELECT
        c.cohort_month,
        COUNT(*) AS cohort_size,

        COUNT(*) FILTER (
            WHERE cl.churn_date IS NULL
               OR cl.churn_date > c.cohort_month + INTERVAL '1 month'
        ) AS active_1_month,

        COUNT(*) FILTER (
            WHERE cl.churn_date IS NULL
               OR cl.churn_date > c.cohort_month + INTERVAL '3 months'
        ) AS active_3_month,

        COUNT(*) FILTER (
            WHERE cl.churn_date IS NULL
               OR cl.churn_date > c.cohort_month + INTERVAL '6 months'
        ) AS active_6_month

    FROM cohorts c
    LEFT JOIN churn_labels cl
        ON c.customer_id = cl.customer_id
    GROUP BY c.cohort_month
)

SELECT
    cohort_month,

    ROUND(
        100.0 * active_1_month / cohort_size, 2
    ) AS retention_1_month,

    ROUND(
        100.0 * active_3_month / cohort_size, 2
    ) AS retention_3_month,

    ROUND(
        100.0 * active_6_month / cohort_size, 2
    ) AS retention_6_month

FROM cohort_activity
ORDER BY cohort_month;

--Q21. Using DENSE_RANK(), rank countries by churn rate (highest to lowest) and return only the top 5.

WITH country_churn AS (
    SELECT
        c.country,
        COUNT(*) AS total_customers,
        COUNT(*) FILTER (WHERE cl.churned = TRUE) AS churned_customers
    FROM customers c
    JOIN churn_labels cl
        ON c.customer_id = cl.customer_id
    GROUP BY c.country
),
ranked AS (
    SELECT
        country,
        ROUND(
            100.0 * churned_customers / total_customers,
            2
        ) AS churn_rate,
        DENSE_RANK() OVER (
            ORDER BY churned_customers::numeric / total_customers DESC
        ) AS country_rank
    FROM country_churn
)
SELECT *
FROM ranked
WHERE country_rank <= 5
ORDER BY country_rank;

--Q22. For every customer, compute a running total of payments made, ordered by payment_date.

SELECT
    customer_id,
    payment_date,
    amount,
    SUM(amount) OVER (
        PARTITION BY customer_id
        ORDER BY payment_date
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS running_total_payments
FROM payments
WHERE payment_status = 'Success'
ORDER BY customer_id, payment_date;

--Q23. Identify customers whose watch time declined for three consecutive months.

WITH monthly_watch AS (
    SELECT
        customer_id,
        DATE_TRUNC('month', viewing_date)::date AS month,
        SUM(watch_duration_minutes) AS watch_minutes
    FROM viewing_activity
    GROUP BY customer_id, month
),
lagged AS (
    SELECT
        *,
        LAG(watch_minutes, 1) OVER (
            PARTITION BY customer_id ORDER BY month
        ) AS previous_month,
        LAG(watch_minutes, 2) OVER (
            PARTITION BY customer_id ORDER BY month
        ) AS two_months_before
    FROM monthly_watch
)
SELECT *
FROM lagged
WHERE watch_minutes < previous_month
  AND previous_month < two_months_before;

--Q24. Calculate the monthly churn rate over the last 12 months.

WITH months AS (
    SELECT generate_series(
        DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '11 months',
        DATE_TRUNC('month', CURRENT_DATE),
        INTERVAL '1 month'
    )::date AS month
),

monthly_churn AS (
    SELECT
        DATE_TRUNC('month', churn_date)::date AS month,
        COUNT(*) AS churned_customers
    FROM churn_labels
    WHERE churned = TRUE
      AND churn_date IS NOT NULL
    GROUP BY 1
),

active_at_start AS (
    SELECT
        m.month,
        COUNT(*) AS active_customers
    FROM months m
    JOIN customers c
        ON c.registration_date < m.month
    LEFT JOIN churn_labels cl
        ON c.customer_id = cl.customer_id
    WHERE cl.churn_date IS NULL
       OR cl.churn_date >= m.month
    GROUP BY m.month
)

SELECT
    m.month,
    COALESCE(mc.churned_customers, 0) AS churned_customers,
    COALESCE(a.active_customers, 0) AS active_customers_at_start,
    ROUND(
        100.0 * COALESCE(mc.churned_customers, 0)
        / NULLIF(a.active_customers, 0),
        2
    ) AS monthly_churn_rate
FROM months m
LEFT JOIN monthly_churn mc
    ON m.month = mc.month
LEFT JOIN active_at_start a
    ON m.month = a.month
ORDER BY m.month;

--Q25. Calculate customer retention rate by acquisition_channel.

SELECT
    c.acquisition_channel,
    COUNT(*) AS total_customers,
    COUNT(*) FILTER (WHERE cl.churned = FALSE) AS active_customers,
    ROUND(
        100.0 *
        COUNT(*) FILTER (WHERE cl.churned = FALSE)
        / COUNT(*),
        2
    ) AS retention_rate
FROM customers c
JOIN churn_labels cl
    ON c.customer_id = cl.customer_id
GROUP BY c.acquisition_channel
ORDER BY retention_rate DESC;

--Q26. Compute each customer's total lifetime spend and rank customers into quartiles using NTILE(4).

WITH lifetime_spend AS (
    SELECT
        c.customer_id,
        COALESCE(
            SUM(p.amount) FILTER (
                WHERE p.payment_status = 'Success'
            ), 0
        ) AS lifetime_spend
    FROM customers c
    LEFT JOIN payments p
        ON c.customer_id = p.customer_id
    GROUP BY c.customer_id
)
SELECT
    customer_id,
    lifetime_spend,
    NTILE(4) OVER (
        ORDER BY lifetime_spend
    ) AS spend_quartile
FROM lifetime_spend
ORDER BY lifetime_spend DESC;

--Q27. Find the top 3 issue_subcategory values by ticket volume, per country.

WITH normalized_tickets AS (
    SELECT
        CASE
            WHEN UPPER(TRIM(c.country)) IN ('AR', 'ARGENTINA') THEN 'Argentina'
            WHEN UPPER(TRIM(c.country)) IN ('AU', 'AUSTRALIA') THEN 'Australia'
            WHEN UPPER(TRIM(c.country)) IN ('BR', 'BRAZIL') THEN 'Brazil'
            WHEN UPPER(TRIM(c.country)) IN ('CA', 'CANADA') THEN 'Canada'
            WHEN UPPER(TRIM(c.country)) IN ('DE', 'GERMANY') THEN 'Germany'
            WHEN UPPER(TRIM(c.country)) IN ('ES', 'SPAIN') THEN 'Spain'
            WHEN UPPER(TRIM(c.country)) IN ('FR', 'FRANCE') THEN 'France'
            WHEN UPPER(TRIM(c.country)) IN ('ID', 'INDONESIA') THEN 'Indonesia'
            WHEN UPPER(TRIM(c.country)) IN ('IN', 'INDIA', 'BHARAT') THEN 'India'
            WHEN UPPER(TRIM(c.country)) IN ('IT', 'ITALY') THEN 'Italy'
            WHEN UPPER(TRIM(c.country)) IN ('JP', 'JAPAN') THEN 'Japan'
            WHEN UPPER(TRIM(c.country)) IN ('KR', 'S. KOREA', 'SOUTH KOREA') THEN 'South Korea'
            WHEN UPPER(TRIM(c.country)) IN ('MX', 'MEXICO') THEN 'Mexico'
            WHEN UPPER(TRIM(c.country)) IN ('NG', 'NIGERIA') THEN 'Nigeria'
            WHEN UPPER(TRIM(c.country)) IN ('PH', 'PHILIPPINES') THEN 'Philippines'
            WHEN UPPER(TRIM(c.country)) IN ('PL', 'POLAND') THEN 'Poland'
            WHEN UPPER(TRIM(c.country)) IN ('ZA', 'SOUTH AFRICA') THEN 'South Africa'
            WHEN UPPER(TRIM(c.country)) IN ('AE', 'UAE', 'U.A.E', 'UNITED ARAB EMIRATES') THEN 'United Arab Emirates'
            WHEN UPPER(TRIM(c.country)) IN ('UK', 'U.K.', 'BRITAIN', 'UNITED KINGDOM') THEN 'United Kingdom'
            WHEN UPPER(TRIM(c.country)) IN ('US', 'USA', 'U.S.A', 'UNITED STATES') THEN 'United States'
            ELSE TRIM(c.country)
        END AS country,
        st.issue_subcategory
    FROM support_tickets st
    JOIN customers c
        ON st.customer_id = c.customer_id
),
category_counts AS (
    SELECT
        country,
        issue_subcategory,
        COUNT(*) AS ticket_volume
    FROM normalized_tickets
    GROUP BY country, issue_subcategory
),
ranked AS (
    SELECT
        country,
        issue_subcategory,
        ticket_volume,
        ROW_NUMBER() OVER (
            PARTITION BY country
            ORDER BY ticket_volume DESC, issue_subcategory
        ) AS rn
    FROM category_counts
)
SELECT
    country,
    issue_subcategory,
    ticket_volume
FROM ranked
WHERE rn <= 3
ORDER BY country, rn;

--Q28. Identify customers with 2+ failed payments in the last 90 days who are also flagged as high churn risk.

WITH latest_date AS (
    SELECT MAX(payment_date) AS max_payment_date
    FROM payments
),

failed_payments AS (
    SELECT
        p.customer_id,
        COUNT(*) AS failed_payment_count
    FROM payments p
    CROSS JOIN latest_date ld
    WHERE p.payment_status = 'Failed'
      AND p.payment_date >= ld.max_payment_date - INTERVAL '90 days'
      AND p.payment_date <= ld.max_payment_date
    GROUP BY p.customer_id
),

active_customers AS (
    SELECT DISTINCT
        s.customer_id,
        sp.plan_name AS current_plan
    FROM subscriptions s
    JOIN subscription_plans sp
        ON s.plan_id = sp.plan_id
    WHERE s.subscription_status = 'Active'
)

SELECT
    fp.customer_id,
    fp.failed_payment_count,
    ac.current_plan
FROM failed_payments fp
JOIN active_customers ac
    ON fp.customer_id = ac.customer_id
WHERE fp.failed_payment_count >= 2
ORDER BY fp.failed_payment_count DESC;



--Q30. For each country: total customers, churned customers, churn rate, average customer lifetime value, and top 1 churn_reason.

WITH lifetime_value AS (
    SELECT
        customer_id,
        SUM(amount) AS lifetime_value
    FROM payments
    WHERE payment_status = 'Success'
    GROUP BY customer_id
),
country_data AS (
    SELECT
        c.country,
        COUNT(*) AS total_customers,
        COUNT(*) FILTER (WHERE cl.churned) AS churned_customers,
        AVG(
            CASE
                WHEN cl.churned THEN lv.lifetime_value
            END
        ) AS avg_churned_ltv
    FROM customers c
    LEFT JOIN churn_labels cl
        ON c.customer_id = cl.customer_id
    LEFT JOIN lifetime_value lv
        ON c.customer_id = lv.customer_id
    GROUP BY c.country
),
reasons AS (
    SELECT
        c.country,
        cl.churn_reason,
        ROW_NUMBER() OVER (
            PARTITION BY c.country
            ORDER BY COUNT(*) DESC
        ) AS rn
    FROM customers c
    JOIN churn_labels cl
        ON c.customer_id = cl.customer_id
    WHERE cl.churned = TRUE
    GROUP BY c.country, cl.churn_reason
)
SELECT
    cd.country,
    cd.total_customers,
    cd.churned_customers,
    ROUND(
        100.0 * cd.churned_customers
        / NULLIF(cd.total_customers, 0),
        2
    ) AS churn_rate,
    ROUND(cd.avg_churned_ltv, 2) AS avg_customer_lifetime_value,
    r.churn_reason AS top_churn_reason
FROM country_data cd
LEFT JOIN reasons r
    ON cd.country = r.country
   AND r.rn = 1
ORDER BY churn_rate DESC;

--Q31. Build an "at-risk revenue" report for currently active customers (top 50).

WITH activity AS (
    SELECT
        customer_id,
        CURRENT_DATE - MAX(viewing_date) AS days_since_last_activity
    FROM viewing_activity
    GROUP BY customer_id
),
payment_stats AS (
    SELECT
        customer_id,
        COUNT(*) FILTER (WHERE payment_status = 'Failed')::numeric
        / NULLIF(COUNT(*), 0) AS failed_payment_rate
    FROM payments
    GROUP BY customer_id
),
tickets AS (
    SELECT
        customer_id,
        COUNT(*) AS support_ticket_count
    FROM support_tickets
    GROUP BY customer_id
),
scored AS (
    SELECT
        c.customer_id,
        s.monthly_price,
        COALESCE(a.days_since_last_activity, 9999) AS days_since_last_activity,
        COALESCE(p.failed_payment_rate, 0) AS failed_payment_rate,
        COALESCE(t.support_ticket_count, 0) AS support_ticket_count
    FROM customers c
    JOIN subscriptions s
        ON c.customer_id = s.customer_id
       AND s.subscription_status = 'Active'
    LEFT JOIN activity a
        ON c.customer_id = a.customer_id
    LEFT JOIN payment_stats p
        ON c.customer_id = p.customer_id
    LEFT JOIN tickets t
        ON c.customer_id = t.customer_id
)
SELECT
    customer_id,
    monthly_price,
    ROUND(
        (
            LEAST(days_since_last_activity / 90.0, 1) * 0.4
            + failed_payment_rate * 0.3
            + LEAST(support_ticket_count / 10.0, 1) * 0.3
        )::numeric,
        4
    ) AS risk_score,
    ROUND(
        (
            (
                LEAST(days_since_last_activity / 90.0, 1) * 0.4
                + failed_payment_rate * 0.3
                + LEAST(support_ticket_count / 10.0, 1) * 0.3
            ) * monthly_price
        )::numeric,
        2
    ) AS at_risk_revenue
FROM scored
ORDER BY at_risk_revenue DESC
LIMIT 50;

--Q32. Identify the top 5 customer complaints per country for the most recent completed quarter.

WITH normalized_customers AS (
    SELECT
        customer_id,
        CASE
            WHEN UPPER(TRIM(country)) IN ('AR', 'ARGENTINA') THEN 'Argentina'
            WHEN UPPER(TRIM(country)) IN ('AU', 'AUSTRALIA') THEN 'Australia'
            WHEN UPPER(TRIM(country)) IN ('BR', 'BRAZIL') THEN 'Brazil'
            WHEN UPPER(TRIM(country)) IN ('CA', 'CANADA') THEN 'Canada'
            WHEN UPPER(TRIM(country)) IN ('DE', 'GERMANY') THEN 'Germany'
            WHEN UPPER(TRIM(country)) IN ('ES', 'SPAIN') THEN 'Spain'
            WHEN UPPER(TRIM(country)) IN ('FR', 'FRANCE') THEN 'France'
            WHEN UPPER(TRIM(country)) IN ('ID', 'INDONESIA') THEN 'Indonesia'
            WHEN UPPER(TRIM(country)) IN ('IN', 'INDIA', 'BHARAT') THEN 'India'
            WHEN UPPER(TRIM(country)) IN ('IT', 'ITALY') THEN 'Italy'
            WHEN UPPER(TRIM(country)) IN ('JP', 'JAPAN') THEN 'Japan'
            WHEN UPPER(TRIM(country)) IN ('KR', 'S. KOREA', 'SOUTH KOREA') THEN 'South Korea'
            WHEN UPPER(TRIM(country)) IN ('MX', 'MEXICO') THEN 'Mexico'
            WHEN UPPER(TRIM(country)) IN ('NG', 'NIGERIA') THEN 'Nigeria'
            WHEN UPPER(TRIM(country)) IN ('PH', 'PHILIPPINES') THEN 'Philippines'
            WHEN UPPER(TRIM(country)) IN ('PL', 'POLAND') THEN 'Poland'
            WHEN UPPER(TRIM(country)) IN ('ZA', 'SOUTH AFRICA') THEN 'South Africa'
            WHEN UPPER(TRIM(country)) IN
                ('AE', 'UAE', 'U.A.E', 'UNITED ARAB EMIRATES')
                THEN 'United Arab Emirates'
            WHEN UPPER(TRIM(country)) IN
                ('UK', 'U.K.', 'BRITAIN', 'UNITED KINGDOM')
                THEN 'United Kingdom'
            WHEN UPPER(TRIM(country)) IN
                ('US', 'USA', 'U.S.A', 'UNITED STATES')
                THEN 'United States'
            ELSE 'Unknown'
        END AS country
    FROM customers
),

quarter_bounds AS (
    SELECT
        DATE_TRUNC('quarter', MAX(ticket_date)) AS current_quarter
    FROM support_tickets
),

complaint_counts AS (
    SELECT
        nc.country,
        st.issue_subcategory,
        COUNT(*) AS complaint_count
    FROM support_tickets st
    JOIN normalized_customers nc
        ON st.customer_id = nc.customer_id
    CROSS JOIN quarter_bounds qb
    WHERE st.ticket_date >= qb.current_quarter - INTERVAL '3 months'
      AND st.ticket_date < qb.current_quarter
    GROUP BY nc.country, st.issue_subcategory
),

ranked AS (
    SELECT
        country,
        issue_subcategory,
        complaint_count,
        ROW_NUMBER() OVER (
            PARTITION BY country
            ORDER BY complaint_count DESC, issue_subcategory
        ) AS rn
    FROM complaint_counts
)

SELECT
    country,
    issue_subcategory,
    complaint_count
FROM ranked
WHERE rn <= 5
ORDER BY country, complaint_count DESC, issue_subcategory;

--Q33. Identify "win-back" candidates: churned customers with customer_lifetime_value in the top quartile.

WITH lifetime_value AS (
    SELECT
        customer_id,
        SUM(amount) AS customer_lifetime_value
    FROM payments
    WHERE payment_status = 'Success'
    GROUP BY customer_id
),
quartiles AS (
    SELECT
        customer_id,
        customer_lifetime_value,
        NTILE(4) OVER (
            ORDER BY customer_lifetime_value
        ) AS ltv_quartile
    FROM lifetime_value
),
engagement AS (
    SELECT
        customer_id,
        AVG(watch_duration_minutes) AS avg_watch_duration
    FROM viewing_activity
    GROUP BY customer_id
)
SELECT
    c.customer_id,
    cl.churn_reason,
    q.customer_lifetime_value,
    e.avg_watch_duration AS last_known_engagement
FROM customers c
JOIN churn_labels cl
    ON c.customer_id = cl.customer_id
JOIN quartiles q
    ON c.customer_id = q.customer_id
LEFT JOIN engagement e
    ON c.customer_id = e.customer_id
WHERE cl.churned = TRUE
  AND q.ltv_quartile = 4
ORDER BY q.customer_lifetime_value DESC;

--Q34. Build a plan-migration analysis and identify the most common migration path.

WITH migrations AS (
    SELECT
        s1.customer_id,
        sp1.plan_name AS from_plan,
        sp2.plan_name AS to_plan,
        s2.subscription_start_date AS change_date
    FROM subscriptions s1
    JOIN subscriptions s2
        ON s1.customer_id = s2.customer_id
       AND s2.subscription_start_date > s1.subscription_start_date
    JOIN subscription_plans sp1
        ON s1.plan_id = sp1.plan_id
    JOIN subscription_plans sp2
        ON s2.plan_id = sp2.plan_id
)
SELECT
    from_plan,
    to_plan,
    COUNT(*) AS migration_count
FROM migrations
GROUP BY from_plan, to_plan
ORDER BY migration_count DESC;

--Q35. Calculate weekly active users (WAU), monthly active users (MAU), and WAU/MAU stickiness over the last 6 months.

WITH weekly AS (
    SELECT
        DATE_TRUNC('week', viewing_date)::date AS week,
        COUNT(DISTINCT customer_id) AS wau
    FROM viewing_activity
    WHERE viewing_date >= DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '5 months'
    GROUP BY 1
),
monthly AS (
    SELECT
        DATE_TRUNC('month', viewing_date)::date AS month,
        COUNT(DISTINCT customer_id) AS mau
    FROM viewing_activity
    WHERE viewing_date >= DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '5 months'
    GROUP BY 1
),
monthly_wau AS (
    SELECT
        m.month,
        m.mau,
        ROUND(AVG(w.wau), 2) AS avg_weekly_active_users
    FROM monthly m
    LEFT JOIN weekly w
        ON w.week >= m.month
       AND w.week < m.month + INTERVAL '1 month'
    GROUP BY m.month, m.mau
)
SELECT
    month,
    avg_weekly_active_users,
    mau,
    ROUND(
        avg_weekly_active_users / NULLIF(mau, 0),
        4
    ) AS wau_mau_stickiness
FROM monthly_wau
ORDER BY month;

--Q36. Identify customers who submitted negative feedback within 14 days of a failed payment or a low-satisfaction support ticket.

WITH negative_feedback AS (
    SELECT
        customer_id,
        feedback_date
    FROM customer_feedback
    WHERE rating <= 2
),
failed_payments AS (
    SELECT
        customer_id,
        payment_date
    FROM payments
    WHERE payment_status = 'Failed'
),
bad_tickets AS (
    SELECT
        customer_id,
        ticket_date
    FROM support_tickets
    WHERE customer_satisfaction_score <= 2
)
SELECT DISTINCT
    nf.customer_id,
    nf.feedback_date
FROM negative_feedback nf
WHERE EXISTS (
    SELECT 1
    FROM failed_payments fp
    WHERE fp.customer_id = nf.customer_id
      AND ABS(nf.feedback_date - fp.payment_date) <= 14
)
OR EXISTS (
    SELECT 1
    FROM bad_tickets bt
    WHERE bt.customer_id = nf.customer_id
      AND ABS(nf.feedback_date - bt.ticket_date) <= 14
)
ORDER BY nf.customer_id;

--Q37. Build a full "customer health score" query combining recency, payment failure rate, support satisfaction, tenure, and current plan.

WITH activity AS (
    SELECT
        customer_id,
        CURRENT_DATE - MAX(viewing_date) AS days_since_last_viewing
    FROM viewing_activity
    GROUP BY customer_id
),
payment_stats AS (
    SELECT
        customer_id,
        COUNT(*) FILTER (WHERE payment_status = 'Failed')::numeric
        / NULLIF(COUNT(*), 0) AS failure_rate
    FROM payments
    GROUP BY customer_id
),
support_stats AS (
    SELECT
        customer_id,
        AVG(customer_satisfaction_score) AS avg_satisfaction
    FROM support_tickets
    WHERE customer_satisfaction_score IS NOT NULL
    GROUP BY customer_id
)
SELECT
    c.customer_id,
    sp.plan_name,
    COALESCE(a.days_since_last_viewing, 9999) AS days_since_last_viewing,
    COALESCE(p.failure_rate, 0) AS payment_failure_rate,
    COALESCE(s.avg_satisfaction, 0) AS avg_support_satisfaction,
    CURRENT_DATE - c.registration_date AS tenure_days,
    ROUND(
        (
            LEAST(COALESCE(a.days_since_last_viewing, 9999) / 90.0, 1) * 40
            + COALESCE(p.failure_rate, 0) * 30
            + (1 - LEAST(COALESCE(s.avg_satisfaction, 0) / 5.0, 1)) * 20
            + (1 - LEAST(
                (CURRENT_DATE - c.registration_date) / 365.0, 1
              )) * 10
        )::numeric,
        2
    ) AS risk_score
FROM customers c
LEFT JOIN activity a
    ON c.customer_id = a.customer_id
LEFT JOIN payment_stats p
    ON c.customer_id = p.customer_id
LEFT JOIN support_stats s
    ON c.customer_id = s.customer_id
LEFT JOIN subscriptions sub
    ON c.customer_id = sub.customer_id
   AND sub.subscription_status = 'Active'
LEFT JOIN subscription_plans sp
    ON sub.plan_id = sp.plan_id
ORDER BY risk_score DESC;



